const raw = $input.first().json;
const payload = raw.body ?? raw;
const itens = Array.isArray(payload.itens_criticos) ? payload.itens_criticos : [];
const temZerado = itens.some((item) => item.nivel === 'ZERADO');
const urgencia = temZerado ? 'CRITICA' : 'ATENCAO';

const linhas = itens.map((item) => {
  const status = item.nivel === 'ZERADO' ? 'ZERADO (pausado automaticamente no cardápio)' : 'BAIXO';
  return `- ${item.nome}: restante ${item.quantidade_atual} un. (mínimo: ${item.estoque_minimo} un.) [${status}]`;
});

const cabecalho = temZerado
  ? `Atenção imediata na loja ${payload.loja_nome} (Pedido #${payload.pedido_id}): há item(ns) zerado(s) e pausado(s) no cardápio.`
  : `Aviso preventivo na loja ${payload.loja_nome} (Pedido #${payload.pedido_id}): há item(ns) com estoque próximo do mínimo.`;

const mensagem = [cabecalho, '', ...linhas].join('\n');

return [
  {
    json: {
      evento: payload.evento || 'ESTOQUE_CRITICO',
      loja_id: payload.loja_id,
      loja_nome: payload.loja_nome || 'Loja',
      pedido_id: payload.pedido_id,
      urgencia,
      tem_zerado: temZerado,
      itens_criticos: itens,
      mensagem,
      gerado_em: payload.gerado_em || new Date().toISOString()
    }
  }
];
